//! The icon set Notra's components use, embedded as SVG with `currentColor` paint so
//! either renderer can tint them. Generated by `scripts/gen-icons.mjs` from
//! `assets/icons`: Lucide (ISC), Hugeicons free icons (`huge-*`) and brand marks.

/// An embedded SVG icon.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Icon {
    ArrowDown,
    ArrowRight,
    ArrowUp,
    AtSign,
    Brain,
    Check,
    ChevronDown,
    ChevronLeft,
    ChevronRight,
    ChevronsUpDown,
    CircleAlert,
    Copy,
    Dices,
    ExternalLink,
    FileText,
    Globe,
    HugeArrowLeft01,
    HugeArrowRight01,
    HugeInformationCircle,
    HugeSearch,
    HugeUnfoldMore,
    LoaderCircle,
    LockKeyhole,
    Mail,
    Map,
    Maximize,
    Mic,
    MinimapChevron,
    Pencil,
    Play,
    Plus,
    RotateCcw,
    Search,
    SquareSolid,
    Square,
    ThumbsDown,
    ThumbsUp,
    Timer,
    Trash2,
    TriangleAlert,
    X,
    ZoomIn,
    ZoomOut,
}

